				window := time.Duration(*dedupWindow) * time.Minute
				existing := findDedupEntry(dedup, rule.ID, alert.SourceIP, now, window)
				if existing != nil {
					if alert.EnrichedRiskScore > existing.alert.EnrichedRiskScore {
						existing.threat = threat
						existing.alert = alert
						existing.refTime = now
						existing.rule = rule
					}
					continue
				}
				entry := &dedupEntry{
					ruleID:      rule.ID,
					sourceIP:    alert.SourceIP,
					refTime:     now,
					threat:      threat,
					alert:       alert,
					rule:        rule,
					emitted:     false,
				}
				dedup = append(dedup, entry)
				continue
			}

			if err := enc.Encode(alert); err != nil {
				fmt.Fprintln(os.Stderr, err)
				return 1
			}
		}
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	if *dedupWindow > 0 {
		for _, entry := range dedup {
			if err := enc.Encode(entry.alert); err != nil {
				fmt.Fprintln(os.Stderr, err)
				return 1
			}
		}
	}
	return 0
}

func loadAlertRules(path string) ([]alertRule, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var rules []alertRule
	if err := json.Unmarshal(data, &rules); err != nil {
		return nil, err
	}
	for i := range rules {
		if rules[i].Conditions.ActorPattern != nil && *rules[i].Conditions.ActorPattern != "" {
			re, err := regexp.Compile("^" + *rules[i].Conditions.ActorPattern + "$")
			if err != nil {
				return nil, fmt.Errorf("invalid actor_pattern in rule %s: %w", rules[i].ID, err)
			}
			rules[i].actorRegex = re
		}
	}
	return rules, nil
}

func matchAlertRule(threat map[string]interface{}, rule alertRule) (bool, alertOutput) {
	threatType, _ := getString(threat, "threat_type")
	sourceIP, _ := getString(threat, "source_ip")
	var enrichedRisk float64
	if v, ok := getFloat(threat, "enriched_risk_score"); ok {
		enrichedRisk = v
	}
	iocSeverity, _ := getString(threat, "ioc_severity")
	actors, _ := getStringSlice(threat, "threat_actors")
	if actors == nil {
		actors = []string{}
	}

	if len(rule.Conditions.ThreatTypes) > 0 {
		if !containsString(rule.Conditions.ThreatTypes, threatType) {
			return false, alertOutput{}
		}
	}
	if rule.Conditions.MinEnrichedRisk != nil {
		if enrichedRisk < *rule.Conditions.MinEnrichedRisk {
			return false, alertOutput{}
		}
	}
	if rule.Conditions.MinSeverityRank != nil {
		if severityValue(iocSeverity) < *rule.Conditions.MinSeverityRank {
			return false, alertOutput{}
		}
	}

	matchedActors := actors
	if rule.actorRegex != nil {
		matchedActors = []string{}
		for _, actor := range actors {
			if rule.actorRegex.MatchString(actor) {
				matchedActors = append(matchedActors, actor)
			}
		}
		if len(matchedActors) == 0 {
			return false, alertOutput{}
		}
	}
	sort.Strings(matchedActors)
	if matchedActors == nil {
		matchedActors = []string{}
	}

	alert := alertOutput{
		RuleID:            rule.ID,
		RuleName:          rule.Name,
		AlertPriority:     float64(rule.Priority) * enrichedRisk,
		ThreatType:        threatType,
		SourceIP:          sourceIP,
		EnrichedRiskScore: enrichedRisk,
		IocSeverity:       iocSeverity,
		ReferenceTime:     alertReferenceTimeString(threat),
		MatchedActors:     matchedActors,
	}
	return true, alert
}

func findDedupEntry(entries []*dedupEntry, ruleID, sourceIP string, now time.Time, window time.Duration) *dedupEntry {
	for _, e := range entries {
		if e.ruleID != ruleID || e.sourceIP != sourceIP {
			continue
		}
		if !e.refTime.Before(now.Add(-window)) && !e.refTime.After(now.Add(window)) {
			return e
		}
	}
	return nil
}

func alertReferenceTime(threat map[string]interface{}) time.Time {
	if ts, ok := getString(threat, "reference_time"); ok {
		if t, err := parseTime(ts); err == nil {
			return t
		}
	}
	return threatReferenceTime(threat)
}

func alertReferenceTimeString(threat map[string]interface{}) string {
	if ts, ok := getString(threat, "reference_time"); ok {
		return ts
	}
	t := threatReferenceTime(threat)
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339)
}

